import json,hashlib,argparse
from pathlib import Path
parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--project',default=str(Path(__file__).resolve().parents[2]));args=parser.parse_args();W=Path(args.project).resolve()
import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
from matplotlib.patches import FancyBboxPatch
BIO='https://openai.com/index/measuring-how-ai-agents-handle-wet-lab-science/'
