def savefig(f,name,url,loc,stats):
 p=D/('nov08-'+name+'.png');f.savefig(p,dpi=160,facecolor='#fafbf7');plt.close(f);u='/report-figures/'+p.name;reg[u]={'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'source_urls':[url],'license':RIGHTS,'version':'OpenAI original HTML; '+('2026-11-06' if 'bio' in name else '2026-11-04'),'origin':'fieldtofit-redraw','statistics':{'locator':loc,**stats}};paths.append({'png':str(p),'url':u})
f,ax=plt.subplots(figsize=(10.5,7));f.subplots_adjust(left=.24,right=.93,top=.78,bottom=.30);f.text(.07,.92,'Mean rubric credit, not experimental success',fontsize=20,weight='bold');f.text(.07,.86,'BioBasicsBench | xhigh | 100 tasks x 5 attempts per model',fontsize=13)
names=['GPT-6 Astra','GPT-6.1 Sol','GPT-5.6 Sol','GPT-6 Luna','GPT-5.5','GPT-5.4','GPT-5.2'];v=[66.7,62.0,43.8,38.3,35.4,33.2,31.2];lo=[60.3,55.6,37.6,32.3,29.7,28.3,26.2];hi=[73.1,68.4,50.0,44.5,41.0,38.4,36.3]
for i,(a,l,h) in enumerate(zip(v,lo,hi)):ax.errorbar(a,i,xerr=[[a-l],[h-a]],fmt='o',capsize=5,color='#2a7863' if i<2 else '#7f8c99',markersize=8);ax.text(h+2,i,f'{a:.1f}%',va='center',fontsize=12)
ax.set(yticks=range(7),yticklabels=names,xlim=(0,100),xlabel='Mean reward (% of available credit)');ax.invert_yaxis();ax.grid(axis='x',alpha=.2);ax.spines[['top','right']].set_visible(False);f.text(.07,.115,'Whiskers: published 95% whole-task bootstrap confidence intervals.\nFive attempts for each task stay together when resampling.',fontsize=12);f.text(.07,.035,'FieldToFit original redraw | OpenAI, 2026-11-06 | No independent reproduction',fontsize=10)
savefig(f,'bio-scores',BIO,'Results; Performance at xhigh reasoning effort',{'metric':'mean rubric reward','unit':'%','means':v,'ci95_low':lo,'ci95_high':hi,'models':names,'tasks':100,'attempts_per_task':5})
def panels(name,title,sub,boxes,foot,url,loc,stats):
 f=plt.figure(figsize=(10.5,7));f.text(.06,.92,title,fontsize=20,weight='bold');f.text(.06,.86,sub,fontsize=12)
 for i,(head,text) in enumerate(boxes):
  x=.06+(i%2)*.46;y=.50-(i//2)*.29;f.patches.append(FancyBboxPatch((x,y),.42,.25,boxstyle='round,pad=0.012',transform=f.transFigure,facecolor='#e6eee7',edgecolor='#9fb9aa'));f.text(x+.02,y+.19,head,fontsize=16,weight='bold');f.text(x+.02,y+.14,text,fontsize=12,va='top',linespacing=1.6)
 f.text(.06,.10,foot,fontsize=11,linespacing=1.5);f.text(.06,.025,'FieldToFit original explanatory diagram | '+('OpenAI, 2026-11-06' if name.startswith('bio') else 'OpenAI, 2026-11-04'),fontsize=10);savefig(f,name,url,loc,stats)
panels('bio-evidence','Evidence is a chain of separate checks','Reading framework; box size does not encode frequency or performance.',[('1. Observe','What is actually visible?\nAre measurements comparable?'),('2. Check controls','Do labels and controls match?\nAre signals separable?'),('3. Restore context','Depth scan or biological change?\nWhat assumptions were added?'),('4. Bound the conclusion','Retain conflicting evidence.\nState what remains uncertain.')],'Examples illustrate failure modes, not their population frequencies.\nA higher score does not remove the need to check controls and final answers.',BIO,'GPT-6 Astra improvements; Where models still fall short',{'kind':'qualitative reading framework','error_incidence_rates':None})
panels('root-counts','Different counters answer different questions','Main run in mid-October 2026 | Numbers are not additive or one success-rate funnel.',[('2,308 candidates','Deduplicated static findings\nNot all dynamically confirmed'),('1,724 reproductions','Observed dynamic behaviour\nUnder the study conditions'),('1,169 working LPE exploits','Successful exploit artefacts\nBefore variant consolidation'),('948 distinct patches','Used to count unique LPEs\nNot 948 deployed upstream fixes')],'291 information-leak proofs are a separate result category.\nCounts retain the original units; boxes are not drawn proportional to counts.',ROOT_URL,'Summary; Vulnerability validation; Exploitability assessment',{'kind':'categorical counters','candidates':2308,'reproductions':1724,'working_LPE_exploits':1169,'distinct_patches':948,'flow_percentages':None})
panels('root-attribution','Validate the assigned path as well as the result','A defensive review framework; no exploit steps or payloads.',[('Assigned target','Which finding was the agent\nsupposed to validate?'),('Actual path','Did evidence use that finding,\na different flaw or infrastructure?'),('Observed result','Did the claimed outcome occur\nunder the stated configuration?'),('Independent review','Match path to target; check patch\nand latest upstream version.')],'Early reviewed sample: 20 of 200 successful exploits used a different vulnerability.\nThis is not a measured mismatch rate for the final campaign.',ROOT_URL,'Using the wrong 0-day; Vulnerabilities in testing infrastructure',{'kind':'qualitative attribution checks','early_successful_sample':200,'early_wrong_target':20,'final_campaign_mismatch_rate':None})
